'use strict';

// MODULES //

var logger = require( 'debug' );
var join = require( '@stdlib/array/base/join' );
var lowercase = require( '@stdlib/string/lowercase' );
var trim = require( '@stdlib/string/trim' );
var replace = require( '@stdlib/string/replace' );
var format = require( '@stdlib/string/format' );
var diagnostic = require( './diagnostic.js' );
var account = require( './account.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:project' );

// Fields in the portable MDAST projection. Positions and parser-specific data are intentionally omitted because provenance is represented separately:
var FIELDS = [
	'value',
	'depth',
	'ordered',
	'start',
	'spread',
	'checked',
	'url',
	'title',
	'identifier',
	'label',
	'referenceType',
	'lang',
	'meta',
	'align',
	'alt'
];


// FUNCTIONS //

/**
* Returns a normalized reference identifier.
*
* @private
* @param {string} value - identifier
* @returns {string} normalized identifier
*/
function normalizeIdentifier( value ) {
	return lowercase( trim( replace( value, /[\t\n\r ]+/g, ' ' ) ) );
}

/**
* Returns indexes of balanced generated related-package span wrappers.
*
* @private
* @param {Array} children - sibling MDAST nodes
* @returns {Object} indexes to normalize
*/
function relatedSpanIndexes( children ) {
	var indexes;
	var opening;
	var stack;
	var child;
	var i;

	indexes = Object.create( null );
	stack = [];

	// Inline HTML is emitted as sibling nodes by remark. Pair spans with a stack so that only balanced wrappers generated by stdlib's related-links tooling can be removed without also removing authored HTML...
	for ( i = 0; i < children.length; i++ ) {
		child = children[ i ];
		if ( child.type !== 'html' ) {
			continue;
		}
		if ( /^<span\b/.test( child.value ) ) {
			stack.push({
				'index': i,
				'generated': (
					/^<span class="(?:package-name|delimiter|description)">$/.test( child.value )
				)
			});
		} else if ( /^<\/span>$/.test( child.value ) && stack.length ) {
			opening = stack.pop();

			// An unknown span may be nested within a generated span. In that case its own open/close pair remains, while the generated outer pair is removed...
			if ( opening.generated ) {
				indexes[ opening.index ] = true;
				indexes[ i ] = true;
				debug( 'Identified generated related span wrapper: openingIndex=%d closingIndex=%d', opening.index, i );
			}
		}
	}
	return indexes;
}

/**
* Reports an undefined reference once.
*
* @private
* @param {Object} state - conversion state
* @param {Object} node - reference node
* @param {string} identifier - normalized identifier
* @returns {void}
*/
function undefinedReference( state, node, identifier ) {
	// Report once per normalized identifier; repeated unresolved references add no new corrective information and would make diagnostics unnecessarily noisy...
	if ( state.undefinedReferences[ identifier ] ) {
		debug( 'Skipping repeated undefined reference diagnostic: identifier=%s', identifier );
		return;
	}
	debug( 'Reporting undefined reference: identifier=%s', identifier );
	state.undefinedReferences[ identifier ] = true;
	diagnostic( state, 'warning', 'undefined-reference', format( 'Reference `%s` has no definition.', identifier ), node, {
		'identifier': identifier
	});
}

/**
* Projects child MDAST nodes.
*
* @private
* @param {Array} children - child nodes
* @param {Object} state - conversion state
* @param {boolean} normalizeSpans - boolean indicating whether to normalize related spans
* @returns {Array} projected children
*/
function projectChildren( children, state, normalizeSpans ) {
	var resource;
	var spans;
	var child;
	var out;
	var i;

	spans = ( normalizeSpans ) ? relatedSpanIndexes( children ) : null;
	out = [];

	for ( i = 0; i < children.length; i++ ) {
		child = children[ i ];
		if ( child.type === 'definition' ) {
			// Definitions are global resources in the semantic document, even when remark nests one inside a block quote or list item...
			resource = state.definitionNodes[
				join( state.provenance.path( child ), '.' )
			];
			debug( 'Removing nested definition from projected flow: resource=%s', resource );
			account( state, child, 'moved-to-resource', 'definition', 'Moved nested link definition to ordered resources.', [ resource ] );
			continue;
		}
		if ( spans && spans[ i ] ) {
			// Accounting for this transformation is performed while inspecting the original tree; projection only omits the characterized wrapper...
			debug( 'Removing generated related span wrapper from projected flow: index=%d', i );
			continue;
		}
		out.push( project( child, state, normalizeSpans ) );
	}
	return out;
}


// MAIN //

/**
* Projects an MDAST node into the portable semantic-document subset.
*
* @private
* @param {Object} node - MDAST node
* @param {Object} state - conversion state
* @param {boolean} [normalizeSpans=false] - boolean indicating whether to normalize generated related spans
* @returns {Object} projected node
*/
function project( node, state, normalizeSpans ) {
	var identifier;
	var definition;
	var children;
	var out;
	var i;

	if ( node.type === 'linkReference' || node.type === 'imageReference' ) {
		// Replace resolvable references with self-contained link/image nodes while retaining a resource reference for traceability to the declaration...
		identifier = normalizeIdentifier( node.identifier );
		definition = state.definitions[ identifier ];
		if ( definition ) {
			out = {
				'type': ( node.type === 'linkReference' ) ? 'link' : 'image',
				'url': definition.url,
				'title': definition.title,
				'definitionRef': definition.id
			};
			if ( node.type === 'linkReference' ) {
				children = node.children;
				children = projectChildren( children, state, normalizeSpans );
				out.children = children;
			} else {
				out.alt = node.alt || '';
			}
			debug( 'Resolved reference during projection: identifier=%s resource=%s type=%s', identifier, definition.id, out.type );
			return out;
		}
		undefinedReference( state, node, identifier );
	}
	// Unknown or unresolved nodes retain their MDAST type, but only the documented portable fields are copied. This avoids leaking positions or plugin metadata...
	out = {
		'type': node.type
	};
	for ( i = 0; i < FIELDS.length; i++ ) {
		if ( node[ FIELDS[ i ] ] !== void 0 ) {
			out[ FIELDS[ i ] ] = node[ FIELDS[ i ] ];
		}
	}
	if ( node.children ) {
		out.children = projectChildren( node.children, state, normalizeSpans );
	}
	return out;
}


// EXPORTS //

project.relatedSpanIndexes = relatedSpanIndexes;
module.exports = project;
